import { tv, type VariantProps } from "@/lib/beton/tv";

/** Scramble, typewriter and counter share one plain typographic surface. */
export const textEffect = tv({
  base: "font-display font-black tracking-tight text-foreground tabular-nums",
  variants: {
    size: {
      sm: "text-h4",
      md: "text-h3",
      lg: "text-h2",
      xl: "text-h1",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const typewriter = tv({
  slots: {
    root: "font-display font-black tracking-tight text-foreground",
    caret: "ml-0.5 inline-block w-[0.6ch] bg-foreground align-baseline motion-safe:animate-blink",
  },
  variants: {
    size: {
      sm: { root: "text-h4", caret: "h-[1em]" },
      md: { root: "text-h3", caret: "h-[1em]" },
      lg: { root: "text-h2", caret: "h-[1em]" },
      xl: { root: "text-h1", caret: "h-[1em]" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const glitchText = tv({
  slots: {
    root: "relative inline-block font-display font-black tracking-tight text-foreground",
    layer: "pointer-events-none absolute inset-0 select-none",
    body: "relative",
    a: "text-primary motion-safe:animate-glitch-a motion-reduce:hidden",
    b: "text-danger motion-safe:animate-glitch-b motion-reduce:hidden",
  },
  variants: {
    size: {
      sm: { root: "text-h4" },
      md: { root: "text-h3" },
      lg: { root: "text-h2" },
      xl: { root: "text-h1" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type TextEffectVariants = VariantProps<typeof textEffect>;
export type TypewriterVariants = VariantProps<typeof typewriter>;
export type GlitchTextVariants = VariantProps<typeof glitchText>;

"use client";

import { textEffect, type TextEffectVariants } from "@/lib/beton/recipes/text-effects.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import { useEffect, useState, type ComponentProps } from "react";
import { useReducedMotion } from "@/lib/beton/use-reduced-motion";

const GLYPHS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#%&@";

export interface ScrambleTextProps
  extends Omit<ComponentProps<"span">, "children">, TextEffectVariants {
  /** The words to settle on. */
  children: string;
  /** Milliseconds between frames. */
  interval?: number;
  /** How many frames each character churns for before it settles. */
  churn?: number;
  /** Scramble again whenever this changes. */
  runKey?: string | number;
}

/**
 * Letters churn through junk and settle into the real words. Screen readers
 * only ever get the real words, and reduced motion skips the churn entirely.
 */
export function ScrambleText({
  size = "md",
  children,
  interval = 40,
  churn = 6,
  runKey,
  className,
  ...props
}: ScrambleTextProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = useState(children);

  useEffect(() => {
    if (reduced) {
      setShown(children);
      return;
    }
    let frame = 0;
    const steps = children.length + churn;
    const timer = setInterval(() => {
      frame += 1;
      if (frame >= steps) {
        setShown(children);
        clearInterval(timer);
        return;
      }
      const settled = Math.max(0, frame - churn);
      setShown(
        children
          .split("")
          .map((character, index) => {
            if (index < settled || character === " ") return character;
            return GLYPHS[Math.floor(Math.random() * GLYPHS.length)];
          })
          .join(""),
      );
    }, interval);
    return () => clearInterval(timer);
  }, [children, churn, interval, reduced, runKey]);

  return (
    <span {...props} className={textEffect({ size, class: className })}>
      <span aria-hidden="true">{shown}</span>
      <span className={visuallyHidden}>{children}</span>
    </span>
  );
}
